#!/usr/bin/env python3  # Execute this one-shot runtime-contract finalizer with the repository interpreter.
"""Finalize WM-VLA runtime adapters and retain a machine-readable solver gate."""  # State the narrow purpose of this temporary script.

from __future__ import annotations  # Enable postponed annotation evaluation.

from pathlib import Path  # Import portable repository-path handling.


def _insert_once(text: str, marker: str, block: str, sentinel: str, label: str) -> str:  # Insert one idempotent source block at a verified marker.
    if sentinel in text:  # Detect an already finalized source tree.
        return text  # Preserve the existing final form.
    if marker not in text:  # Reject an unknown source revision.
        raise RuntimeError(f"missing insertion marker: {label}")  # Surface the incompatible source location.
    return text.replace(marker, block + marker, 1)  # Insert exactly one audited block.


def _finalize_controller(root: Path) -> None:  # Add structural adapters around existing repository contracts.
    path = root / "visionamr" / "vla" / "world_controller.py"  # Select the canonical controller source.
    text = path.read_text(encoding="utf-8")  # Read the exact branch source.
    import_marker = "import inspect  # Import constructor signature inspection for repository compatibility.\n"  # Identify the expected finalized import.
    if import_marker not in text:  # Support a branch where the earlier one-shot finalizer did not commit.
        hash_import = "import hashlib  # Import hashing for immutable action and mesh receipts.\n"  # Identify the original stable import.
        if hash_import not in text:  # Reject an incompatible controller revision.
            raise RuntimeError("missing controller hashing import")  # Stop before a speculative edit.
        text = text.replace(hash_import, hash_import + import_marker, 1)  # Add signature inspection exactly once.
    helper_marker = "\n\ndef semantic_persistence(name: str) -> float:"  # Identify the stable helper insertion point.
    helper = '''\n\ndef _record_equations(record) -> int:  # Read the actual CalculiX equation count across repository record revisions.\n    for field in ("n_equations", "n_eq", "equations"):  # Enumerate supported explicit record fields.\n        value = getattr(record, field, None)  # Read one candidate field safely.\n        if value is not None:  # Accept the first materialized count.\n            return int(value)  # Return a normalized integer equation count.\n    extra = getattr(record, "extra", {}) or {}  # Read structured diagnostics as a final compatibility path.\n    for field in ("n_equations", "n_eq", "equations"):  # Enumerate supported diagnostic keys.\n        if field in extra:  # Accept an explicitly recorded equation count.\n            return int(extra[field])  # Return the normalized diagnostic count.\n    raise AttributeError("solve record contains no equation count")  # Reject unauditable resource accounting.\n\n\ndef _partition_assign(partition, mesh: Mesh) -> np.ndarray:  # Apply the fixed semantic partition across repository method spellings.\n    for name in ("assign", "assign_cells", "labels"):  # Enumerate supported assignment method names.\n        method = getattr(partition, name, None)  # Read one candidate method.\n        if callable(method):  # Require an executable assignment method.\n            values = method(mesh)  # Apply the semantic partition to the realized Gmsh mesh.\n            labels = np.asarray(values, dtype=int)  # Normalize the assignment to integral region labels.\n            if labels.shape != (mesh.n_cells,):  # Require exactly one stable region per element.\n                raise ValueError("partition assignment width does not match the mesh")  # Reject a malformed semantic state.\n            return labels  # Return the validated element labels.\n    raise AttributeError("partition exposes no cell-assignment method")  # Reject an unsupported repository contract.\n\n\ndef _partition_features(partition, post, eta2: np.ndarray, labels: np.ndarray):  # Aggregate solve evidence across repository method spellings.\n    for name in ("features", "aggregate_features", "region_features"):  # Enumerate supported regional aggregation methods.\n        method = getattr(partition, name, None)  # Read one candidate method.\n        if not callable(method):  # Skip absent aggregation methods.\n            continue  # Search the next supported spelling.\n        parameters = inspect.signature(method).parameters  # Read the bound-method argument contract.\n        context = {"post": post, "state": post, "solution": post, "eta2": eta2, "indicator": eta2, "indicators": eta2, "labels": labels, "assignment": labels, "mesh": post.mesh}  # Map semantic argument names to observed data.\n        kwargs: dict[str, object] = {}  # Allocate accepted keyword arguments only.\n        unresolved: list[str] = []  # Track required arguments not represented by the compatibility map.\n        for parameter_name, parameter in parameters.items():  # Resolve each declared bound-method parameter.\n            if parameter.kind in (inspect.Parameter.VAR_POSITIONAL, inspect.Parameter.VAR_KEYWORD):  # Ignore variadic compatibility escape hatches.\n                continue  # Resolve explicit parameters only.\n            if parameter_name in context:  # Supply a known semantic argument.\n                kwargs[parameter_name] = context[parameter_name]  # Store the exact observed value.\n            elif parameter.default is inspect.Parameter.empty:  # Record an unsupported required argument.\n                unresolved.append(parameter_name)  # Preserve the exact missing field name.\n        if unresolved:  # Try the next method spelling when this signature is incompatible.\n            continue  # Avoid speculative positional calls.\n        return method(**kwargs)  # Return the repository regional-feature object.\n    raise AttributeError("partition exposes no compatible regional-feature method")  # Reject an unsupported aggregation contract.\n\n\ndef _partition_adjacency(partition, mesh: Mesh, labels: np.ndarray, n_regions: int) -> np.ndarray:  # Build the stable semantic graph with a deterministic fallback.\n    for name in ("adjacency_matrix", "region_adjacency", "adjacency"):  # Enumerate supported graph methods.\n        method = getattr(partition, name, None)  # Read one candidate method.\n        if not callable(method):  # Skip absent graph methods.\n            continue  # Search the next supported spelling.\n        parameters = inspect.signature(method).parameters  # Read the bound-method argument contract.\n        context = {"mesh": mesh, "labels": labels, "assignment": labels}  # Map graph argument names to current data.\n        kwargs: dict[str, object] = {}  # Allocate accepted keyword arguments only.\n        unresolved: list[str] = []  # Track unsupported required arguments.\n        for parameter_name, parameter in parameters.items():  # Resolve each declared bound-method parameter.\n            if parameter.kind in (inspect.Parameter.VAR_POSITIONAL, inspect.Parameter.VAR_KEYWORD):  # Ignore variadic parameters.\n                continue  # Resolve explicit parameters only.\n            if parameter_name in context:  # Supply a known graph argument.\n                kwargs[parameter_name] = context[parameter_name]  # Store the exact current value.\n            elif parameter.default is inspect.Parameter.empty:  # Record an unsupported required argument.\n                unresolved.append(parameter_name)  # Preserve the missing name.\n        if unresolved:  # Try another repository graph spelling when incompatible.\n            continue  # Avoid speculative positional calls.\n        matrix = np.asarray(method(**kwargs), dtype=float)  # Normalize the repository graph matrix.\n        if matrix.shape == (n_regions, n_regions):  # Accept only a complete square semantic graph.\n            return matrix  # Return the validated graph matrix.\n    matrix = np.zeros((n_regions, n_regions), dtype=float)  # Allocate the deterministic face-adjacency fallback graph.\n    pairs, _ = mesh.cell_adjacency  # Read all face-adjacent simplex pairs.\n    for left, right in np.asarray(pairs, dtype=int):  # Visit every neighboring element pair.\n        left_region = int(labels[left])  # Read the first element's semantic region.\n        right_region = int(labels[right])  # Read the second element's semantic region.\n        if left_region == right_region:  # Ignore graph edges internal to one semantic region.\n            continue  # Preserve only cross-region interaction edges.\n        matrix[left_region, right_region] = 1.0  # Add the directed forward graph edge.\n        matrix[right_region, left_region] = 1.0  # Add the symmetric reverse graph edge.\n    return matrix  # Return the deterministic semantic adjacency graph.\n'''
    text = _insert_once(text, helper_marker, helper, "def _record_equations(record)", "controller runtime helpers")  # Insert all structural adapters once.
    text = text.replace("features = partition.features(post, eta2, labels)  # Aggregate element-wise physical evidence by stable semantic region.", "features = _partition_features(partition, post, eta2, labels)  # Aggregate element-wise physical evidence through the repository-compatible adapter.")  # Adapt regional aggregation.
    text = text.replace("adjacency = partition.adjacency_matrix(post.mesh, labels)  # Build the realized semantic-region adjacency graph.", "adjacency = _partition_adjacency(partition, post.mesh, labels, n_regions)  # Build the realized semantic graph through the repository-compatible adapter.")  # Adapt semantic graph construction.
    text = text.replace("labels = partition.assign(mesh)  # Reapply the fixed semantic drawings to the realized Gmsh mesh.", "labels = _partition_assign(partition, mesh)  # Reapply the fixed semantic partition through the repository-compatible adapter.")  # Adapt mesh assignment.
    text = text.replace("record.n_equations, step, hit_count", "_record_equations(record), step, hit_count")  # Adapt observed equation-count extraction.
    text = text.replace("if record.n_equations >= n_eq_cap:", "if _record_equations(record) >= n_eq_cap:")  # Adapt resource-stop accounting.
    text = text.replace("if not receipt.budget_pass and receipt.fallback_used:", "if not receipt.budget_pass:")  # Enforce the corrected all-action budget stop idempotently.
    path.write_text(text, encoding="utf-8")  # Write the finalized controller source.


def _finalize_campaign(root: Path) -> None:  # Make vision-head discovery structural rather than filename-dependent.
    path = root / "scripts" / "run_world_model_vla_bridge.py"  # Select the held-out campaign source.
    text = path.read_text(encoding="utf-8")  # Read the exact branch source.
    import_marker = "import math  # Import finite-value and square-root utilities.\n"  # Identify the stable standard-library import insertion point.
    package_import = "import pkgutil  # Import package traversal for structural vision-head discovery.\n"  # Define the additional discovery dependency.
    if package_import not in text:  # Insert package traversal only once.
        if import_marker not in text:  # Reject an incompatible campaign revision.
            raise RuntimeError("missing campaign math import")  # Stop before a speculative source edit.
        text = text.replace(import_marker, import_marker + package_import, 1)  # Add package traversal after scalar utilities.
    start = text.index("def _make_partitioner() -> Any:")  # Locate the deterministic discovery function.
    end = text.index("\n\ndef _record_equations", start)  # Locate the next stable campaign function.
    replacement = '''def _make_partitioner() -> Any:  # Discover the existing semantic vision head by structural contract.\n    package = importlib.import_module("visionamr.vla")  # Import the repository VLA package.\n    module_names = ["visionamr.vla.vision", "visionamr.vla.eye", "visionamr.vla.heads", "visionamr.vla.pipeline"]  # Seed discovery with historically used module locations.\n    package_paths = list(getattr(package, "__path__", []))  # Read the package search paths for installed-module traversal.\n    for module_info in pkgutil.iter_modules(package_paths, package.__name__ + "."):  # Enumerate every current VLA module.\n        if module_info.name not in module_names:  # Preserve stable seed order while adding current modules.\n            module_names.append(module_info.name)  # Add the discovered module exactly once.\n    preferred_names = ("ScriptedVisionPartitioner", "ScriptedVisionHead", "ScriptedEye", "ScriptedVision", "CachedDrawingPartitioner", "CachedDrawingEye", "VisionPartitioner")  # Rank deterministic or cached semantic heads before generic classes.\n    for module_name in module_names:  # Search each current repository VLA module.\n        try:  # Isolate optional module dependencies.\n            module = importlib.import_module(module_name)  # Import one candidate module.\n        except Exception:  # Skip modules requiring unavailable optional services.\n            continue  # Search the next module without weakening the finite-element path.\n        ordered: list[tuple[str, object]] = []  # Allocate a stable class candidate sequence.\n        for name in preferred_names:  # Add explicitly preferred class names first.\n            candidate = getattr(module, name, None)  # Read the named candidate safely.\n            if inspect.isclass(candidate):  # Retain only constructible classes.\n                ordered.append((name, candidate))  # Preserve the preferred class order.\n        for name, candidate in inspect.getmembers(module, inspect.isclass):  # Add structurally plausible classes not already listed.\n            lowered = name.lower()  # Normalize the class name for filtering.\n            if not any(token in lowered for token in ("script", "cached", "vision", "eye", "partitioner")):  # Exclude unrelated classes.\n                continue  # Search the next class.\n            if all(candidate is not existing for _, existing in ordered):  # Avoid duplicate class attempts.\n                ordered.append((name, candidate))  # Append the structurally plausible class.\n        for _, candidate in ordered:  # Attempt deterministic constructor variants in stable order.\n            for kwargs in ({}, {"seed": 0}, {"random_seed": 0}):  # Try common no-service constructor contracts.\n                try:  # Isolate constructor signature differences.\n                    instance = candidate(**kwargs)  # Construct one semantic vision head.\n                except Exception:  # Skip constructors requiring external clients or mandatory fixtures.\n                    continue  # Try the next deterministic constructor form.\n                if callable(getattr(instance, "propose", None)):  # Require the exact semantic-region proposal contract.\n                    return instance  # Return the repository-compatible vision head.\n    raise RuntimeError("no deterministic or cached VLA partitioner with propose(problem) was found")  # Fail explicitly instead of replacing VLA with a non-visual baseline.\n'''
    text = text[:start] + replacement + text[end:]  # Replace only the discovery function.
    path.write_text(text, encoding="utf-8")  # Write the finalized campaign source.


def main() -> None:  # Apply all runtime-contract edits from the repository root.
    root = Path(__file__).resolve().parents[1]  # Resolve the checked-out repository root deterministically.
    _finalize_controller(root)  # Adapt current finite-element and partition interfaces.
    _finalize_campaign(root)  # Adapt semantic vision-head discovery.


if __name__ == "__main__":  # Execute only when launched as the one-shot maintenance script.
    main()  # Apply the deterministic runtime finalization edits.
